import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public class Main {
    public static void main(String[] args) throws Exception {
        CountDownLatch siap = new CountDownLatch(3);
        AtomicInteger hadir = new AtomicInteger();
        for (int i = 1; i <= 3; i++) {
            long jeda = i * 100L;
            new Thread(() -> {
                Jeda.ms(jeda);
                hadir.incrementAndGet();
                siap.countDown();
            }).start();
        }
        siap.await();
        System.out.println("Hadir: " + hadir.get() + ", sisa hitungan: " + siap.getCount());
    }
}

class Jeda {
    static void ms(long ms) {
        try {
            Thread.sleep(ms);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }
}

